import * as React from "react"

import { value as bound, count as boundCount } from "./bindings"

/* ============================================================
 *  SECTION RENDERERS   (WTM-022)
 * ============================================================
 *  Generated from the Template Maker's own SectionShapes by
 *  scripts/port-shapes — the SHAPES map below is lifted verbatim,
 *  which is the whole point: one description of what a section
 *  looks like, used by the builder's preview and by the exported
 *  site. A design cannot render one way in one and another way in
 *  the other, because there is only one of it.
 *
 *  Do not edit this file. Edit SectionShapes and re-run the port.
 *
 *  The differences are deliberate and few:
 *    - a photo is an image, not a button that opens a picker
 *    - repeating things count down to what the host actually has
 *    - every field reads through the bindings, so the contractor's
 *      own name, services and pictures land in the design's slots
 * ============================================================ */

const pad = (n) => String(n).padStart(2, "0")

const counts = (n) => Array.from({ length: n }, (_, i) => i + 1)

function initialsOf(name) {
  return String(name || "")
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word.charAt(0).toUpperCase())
    .join("")
}

/**
 * The shape context. Same surface the builder's renderers expect, so the
 * lifted SHAPES map needs no edits: `v` reads a field, `img` reads a picture,
 * `has` asks whether this section has such a field at all.
 */
function shapeContext(section, view, position, nav) {
  const fields = section.fields || {}
  return {
    definition: { label: section.label || "", fields: [] },
    num: pad(position),
    view,
    has: (key) => Object.prototype.hasOwnProperty.call(fields, key),
    v: (key) => bound(view, key, fields[key], section),
    img: (key) => bound(view, key, fields[key], section),
    // The picker does not exist here. Kept so the lifted map can call it.
    onPickImage: () => {},
    nav,
  }
}

/**
 * The links, and the button that opens them on a phone.
 *
 * Both come from one helper because they are one control: a narrow header
 * sheds the phone number, then the quote button, then puts the links behind a
 * menu icon and drops them down as a panel — which is what the site this was
 * composed from does, and what a visitor expects a header to do. The shedding
 * is in the stylesheet; what has to be here is the pair, as siblings of the
 * bar so the flex row still sees them, which is what the fragment is for.
 *
 * The one difference from the builder: these are real anchors. In the builder
 * a header link is a label, because clicking the header selects the section.
 * On a site it is a link, and it has to go where it says.
 */
function HeaderMenu({ ctx }) {
  const [open, setOpen] = React.useState(false)
  const links = ctx.nav.filter((link) => link.enabled)

  return (
    <>
      <nav className="tm-header-links" data-open={open ? "true" : undefined}>
        {links.map((link) => (
          <a key={link.nodeId} href={link.href} onClick={() => setOpen(false)}>
            {link.label}
          </a>
        ))}
      </nav>
      <button
        type="button"
        className="tm-header-burger"
        aria-label={open ? "Close menu" : "Open menu"}
        aria-expanded={open}
        onClick={() => setOpen((was) => !was)}
      >
        {open ? "✕" : "☰"}
      </button>
    </>
  )
}

function headerMenu(ctx) {
  return <HeaderMenu ctx={ctx} />
}

/**
 * A section composed in the Section Maker.   (WTM-038)
 *
 * The plan travels in a field — rows, the grid each uses, and the bands in
 * each column — so one renderer draws every composed section rather than one
 * per design. It reads a field like any other shape, which is the whole
 * reason it works out here as well as in the builder.
 */
function composedPlan(raw) {
  try {
    const parsed = JSON.parse(raw || "{}")
    const rows = Array.isArray(parsed.rows) ? parsed.rows : []
    return {
      rows: rows.map((row) => ({
        template: typeof row?.template === "string" && row.template ? row.template : "1fr",
        columns: Array.isArray(row?.columns)
          ? row.columns.map((column) => (Array.isArray(column) ? column.map(String) : []))
          : [],
      })),
    }
  } catch {
    // A plan that will not parse draws the heading rather than nothing.
    return { rows: [] }
  }
}

function composedBand(ctx, kind, key) {
  // WTM-046. The three blocks a header is made of.
  if (kind === "brand") {
    return (
      <span key={key} className="tm-header-brand">
        <span className="tm-monogram tm-header-logo" aria-hidden="true">{initialsOf(ctx.v("brandName"))}</span>
        <span>
          <strong>{ctx.v("brandName")}</strong>
          <small>{ctx.v("brandTagline")}</small>
        </span>
      </span>
    )
  }

  if (kind === "nav") {
    return (
      <nav key={key} className="tm-header-links">
        {counts(4).map((n) => <i key={n}>{ctx.v(`link${n}`)}</i>)}
      </nav>
    )
  }

  if (kind === "quote-cta") {
    return (
      <span key={key} className="tm-section-actions">
        <span className="tm-header-phone">
          <small>{ctx.v("phoneLabel")}</small>
          <strong>{ctx.v("phone")}</strong>
        </span>
        <span className="tm-preview-cta">{ctx.v("ctaText")}</span>
      </span>
    )
  }

  if (kind === "highlight") return <span key={key} className="tm-section-eyebrow">{ctx.v("eyebrow")}</span>
  if (kind === "title") return <h2 key={key}>{ctx.v("title")}</h2>
  if (kind === "subtitle") return <p key={key}>{ctx.v("subtitle")}</p>

  if (kind === "quick-info") {
    return (
      <div className="tm-point-row" data-count={3} key={key}>
        {counts(3).map((n) => (
          <div className="tm-point" key={n}>
            <strong>{ctx.v(`point${n}`)}</strong>
            <span>{ctx.v(`point${n}Note`)}</span>
          </div>
        ))}
      </div>
    )
  }

  if (kind === "double-button") {
    return (
      <span className="tm-section-actions" key={key}>
        <span className="tm-preview-cta">{ctx.v("button")}</span>
        <span className="tm-preview-cta is-ghost">{ctx.v("buttonSecondary")}</span>
      </span>
    )
  }

  if (kind === "social-proof") {
    return (
      <span className="tm-proof-line" key={key}>
        {stars()}
        <span>{ctx.v("quote")}</span>
      </span>
    )
  }

  if (kind === "form") {
    return (
      <div className="tm-form-card" key={key}>
        <strong>{ctx.v("formTitle")}</strong>
        {["field1", "field2", "field3"].map((field) => (
          <span className="tm-form-input" key={field}>{ctx.v(field)}</span>
        ))}
        <span className="tm-form-submit">{ctx.v("submit")}</span>
        <small>{ctx.v("formNote")}</small>
      </div>
    )
  }

  return null
}

function composed(ctx) {
  const plan = composedPlan(ctx.v("composed"))
  if (plan.rows.length === 0) {
    return (
      <div className="tm-section-content">
        <h2>{ctx.v("title")}</h2>
        <p>{ctx.v("subtitle")}</p>
      </div>
    )
  }

  return (
    <div className="tm-composed">
      {plan.rows.map((row, index) => (
        <div className="tm-composed-row" key={index} style={{ gridTemplateColumns: row.template }}>
          {row.columns.map((bands, position) => (
            <div className="tm-composed-col" key={position}>
              {bands.map((band, at) => composedBand(ctx, band, at))}
            </div>
          ))}
        </div>
      ))}
    </div>
  )
}

/**
 * Two letters from the business name, standing in for a logo.
 *
 * "Valley Roofing" -> "VR". The host works the same two letters out itself, so
 * use its answer where there is one rather than a second opinion that could
 * disagree with the rest of the site.
 */
function monogram(ctx, options = {}) {
  const view = ctx.view || {}
  const letters = view.initials || initialsOf(view.name)
  if (!letters) return null
  return (
    <span
      key={options.listKey}
      className={["tm-monogram", options.className || ""].filter(Boolean).join(" ")}
      aria-hidden="true"
    >
      {letters}
    </span>
  )
}

/**
 * A picture, or the branded panel when there is none to show.
 *
 * The logo is the exception. Free Contractor Services never asks a contractor
 * for a logo file, so that slot is empty on nearly every site it builds — and
 * an empty grey panel sitting beside the business name reads as a broken
 * image rather than as a design. Where there is no logo the initials of the
 * name stand in, which is what the host's own templates do.
 */
function photo(ctx, key, options = {}) {
  const src = ctx.img(key)
  if (!src && key === "imageLogo") return monogram(ctx, options)
  const classes = ["tm-photo", options.tall ? "is-tall" : "", options.className || ""]
    .filter(Boolean)
    .join(" ")
  return (
    <span
      key={options.listKey}
      className={classes}
      data-empty={src ? undefined : "true"}
      data-slot={key}
      style={src ? { backgroundImage: `url("${src}")` } : undefined}
      role={src ? "img" : undefined}
      aria-label={src ? options.alt || "" : undefined}
    >
      {options.caption ? <i aria-hidden="true">{options.caption}</i> : null}
    </span>
  )
}

function stars(value) {
  return (
    <span className="tm-stars">
      {"\u2605\u2605\u2605\u2605\u2605"}
      {value ? <b>{value}</b> : null}
    </span>
  )
}

function avatar(name) {
  return (
    <span className="tm-avatar" aria-hidden="true">
      {initialsOf(name) || "\u2013"}
    </span>
  )
}

function copy(ctx, hideActions) {
  const showPrimary = !hideActions && ctx.has("button")
  const showSecondary = !hideActions && ctx.has("buttonSecondary")
  return (
    <div className="tm-section-content">
      {ctx.has("eyebrow") ? <span className="tm-section-eyebrow">{ctx.v("eyebrow")}</span> : null}
      {ctx.has("title") ? <h2>{ctx.v("title")}</h2> : null}
      {ctx.has("subtitle") ? <p>{ctx.v("subtitle")}</p> : null}
      {showPrimary || showSecondary ? (
        <span className="tm-section-actions">
          {showPrimary ? <span className="tm-preview-cta">{ctx.v("button")}</span> : null}
          {showSecondary ? (
            <span className="tm-preview-cta is-ghost">{ctx.v("buttonSecondary")}</span>
          ) : null}
        </span>
      ) : null}
    </div>
  )
}

function headingSplit(ctx) {
  return (
    <div className="tm-heading-split">
      <div className="tm-section-content">
        {ctx.has("eyebrow") ? <span className="tm-section-eyebrow">{ctx.v("eyebrow")}</span> : null}
        <h2>{ctx.v("title")}</h2>
      </div>
      <p className="tm-heading-lead">{ctx.v("subtitle")}</p>
    </div>
  )
}

function statRow(ctx, count, className) {
  return (
    <div className={className} data-count={count}>
      {counts(count).map((i) => (
        <div className="tm-stat" key={i}>
          <strong>{ctx.v(`stat${i}`)}</strong>
          <span>{ctx.v(`stat${i}Label`)}</span>
        </div>
      ))}
    </div>
  )
}

function pointList(ctx, count, className) {
  return (
    <div className={className} data-count={count}>
      {counts(count).map((i) => (
        <div className="tm-point" key={i}>
          <strong>{ctx.v(`point${i}`)}</strong>
          {ctx.has(`point${i}Note`) ? <span>{ctx.v(`point${i}Note`)}</span> : null}
        </div>
      ))}
    </div>
  )
}

function stepList(ctx, count) {
  return (
    <div className="tm-steps" data-count={count}>
      {counts(count).map((i) => (
        <div className="tm-step" key={i}>
          <em>{pad(i)} \u2014</em>
          <strong>{ctx.v(`step${i}`)}</strong>
          <span>{ctx.v(`step${i}Desc`)}</span>
        </div>
      ))}
    </div>
  )
}

/** Tiles come from the gallery, so a short gallery draws a short grid. */
function tiles(ctx, count, numbered) {
  const shown = boundCount(ctx.view, "gallery", count)
  return (
    <div className="tm-tiles" data-count={shown}>
      {counts(shown).map((i) =>
        photo(ctx, `image${i}`, {
          className: "tm-tile",
          caption: numbered ? pad(i) : undefined,
          listKey: i,
        }),
      )}
    </div>
  )
}

function formCard(ctx) {
  const rows = ["field1", "field2", "field3"].filter((key) => ctx.has(key)).map((key) => ctx.v(key))
  return (
    <div className="tm-form-card">
      <strong>{ctx.v("formTitle")}</strong>
      {rows.map((row, i) => (
        <span className="tm-form-input" key={`${row}-${i}`}>
          {row}
        </span>
      ))}
      <span className="tm-form-submit">{ctx.v("submit")}</span>
      {ctx.has("formNote") ? <small>{ctx.v("formNote")}</small> : null}
    </div>
  )
}

function quoteCard(ctx, standalone) {
  return (
    <div className={`tm-review-card ${standalone ? "is-standalone" : ""}`}>
      <em aria-hidden="true">{"\u201c"}</em>
      <p>{ctx.v("quote")}</p>
      <span className="tm-review-by">
        {avatar(ctx.v("author"))}
        <span>
          <strong>{ctx.v("author")}</strong>
          {stars(standalone ? ctx.v("rating") : undefined)}
        </span>
      </span>
    </div>
  )
}

function signature(ctx) {
  return (
    <span className="tm-signature">
      {avatar(ctx.v("author"))}
      <span>
        <strong>{ctx.v("author")}</strong>
        <small>{ctx.v("authorMeta")}</small>
      </span>
    </span>
  )
}

