/** The variants whose picture is the section's own background. */
const BACKDROP = {
  "hero-split": "side",
  "hero-form": "side",
  "hero-photo-review": "side",
  "cta-trust": "side",
  "hero-logo": "centred",
  "contact-photo": "centred",
  "hero-benefits-form": "side",
  "cta-photo-phone": "centred",
}

export function backdropStyle(section, view) {
  const kind = BACKDROP[section.variant]
  if (!kind) return undefined
  const src = bound(view, "image", (section.fields || {}).image)
  if (!src) return undefined
  const overlay = kind === "centred" ? "var(--hero-overlay-centred)" : "var(--hero-overlay)"
  return { backgroundImage: `${overlay}, url("${src}")` }
}

/* -- navigation ----------------------------------------------------------- */

/**
 * Which pools a header links to, and what the link is called.
 *
 * The same table the builder derives its nav from, so the preview's links and
 * the exported site's links are the same links.
 */
const LINKABLE = {
  "About us": "About",
  Services: "Services",
  Process: "How it works",
  "Our work": "Past projects",
  Testimonials: "Reviews",
  "Call to action": "Request quote",
  Contact: "Contact",
}

/** The anchor a section answers to. Stable, and derived from its pool. */
export function anchorFor(category) {
  return String(category || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
}

/**
 * The nav, built from the sections actually on the page.
 *
 * A link can never point at a section that is not there, because the list is
 * made from the sections that are. Overrides the author set in Config travel
 * on the header section under `nav:` keys and are applied here, so a renamed
 * or switched-off link stays renamed or switched off on the site.
 */
export function navigationLinks(sections) {
  const header = sections.find((section) => section.category === "Header")
  const overrides = (header && header.fields) || {}
  const seen = new Set()
  const links = []

  sections.forEach((section, index) => {
    const label = LINKABLE[section.category]
    if (!label || seen.has(section.category)) return
    seen.add(section.category)
    const id = `${anchorFor(section.category)}-${index}`
    const nodeId = section.nodeId || id
    if (overrides[`nav:${nodeId}`] === "off") return
    links.push({
      nodeId,
      href: `#${anchorFor(section.category)}`,
      label: (overrides[`nav:${nodeId}:label`] || "").trim() || label,
      enabled: true,
      overridden: Boolean((overrides[`nav:${nodeId}:label`] || "").trim()),
      index,
      targetTitle: section.fields && section.fields.title ? section.fields.title : label,
    })
  })

  return links
}

/** One section, rendered. Unknown variants draw nothing rather than throwing. */
export function renderSection(section, view, position, nav) {
  const render = SHAPES[section.variant]
  if (!render) return null
  return render(shapeContext(section, view, position, nav || []))
}

export const KNOWN_VARIANTS = Object.keys(SHAPES)
